SELECT id, txn_type, amount, merchant, is_flagged, COUNT(amount) OVER (ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_count_30d, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY amount, id) AS row_seq, LEAD(amount, 2) OVER (PARTITION BY merchant, txn_type ORDER BY txn_time, id) AS next_amount, SUM(amount) OVER (ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY txn_time DESC, id) AS event_seq FROM transactions;
